// Native AOT (net10.0) only: exposes the XAML input/XBF output streams to GenXbf.dll as COM IStream objects through
// source-generated COM (System.Runtime.InteropServices.ComTypes.IStream relies on built-in COM interop instead). The COM
// interfaces are generated by CsWin32 (see NativeMethods.txt).
// Not implemented members throw NotImplementedException, which is returned to native code as E_NOTIMPL.

namespace Microsoft.UI.Xaml.Markup.Compiler.FileIO
{
    using System;
    using System.IO;
    using System.Runtime.InteropServices.Marshalling;
    using Windows.Win32.Foundation;
    using Windows.Win32.System.Com;

    [GeneratedComClass]
    internal unsafe partial class StreamImpl : Windows.Win32.System.Com.IStream
    {
        HRESULT ISequentialStream.Read(void* pv, uint cb, uint* pcbRead)
        {
            if (!_underlyingStream.CanRead)
            {
                throw new InvalidOperationException();
            }
            int cntRead = _underlyingStream.Read(new Span<byte>(pv, checked((int)cb)));
            if (pcbRead != null)
            {
                *pcbRead = (uint)cntRead;
            }
            return default; // S_OK
        }

        HRESULT ISequentialStream.Write(void* pv, uint cb, uint* pcbWritten)
        {
            if (!_underlyingStream.CanWrite)
            {
                throw new InvalidOperationException();
            }
            _underlyingStream.Write(new ReadOnlySpan<byte>(pv, checked((int)cb)));
            if (pcbWritten != null)
            {
                *pcbWritten = cb;
            }
            return default; // S_OK
        }

        void Windows.Win32.System.Com.IStream.Seek(long dlibMove, SeekOrigin dwOrigin, ulong* plibNewPosition)
        {
            if (!_underlyingStream.CanSeek)
            {
                throw new InvalidOperationException();
            }
            long newPos = _underlyingStream.Seek(dlibMove, dwOrigin);
            if (plibNewPosition != null)
            {
                *plibNewPosition = (ulong)newPos;
            }
        }

        void Windows.Win32.System.Com.IStream.SetSize(ulong libNewSize)
        {
            _underlyingStream.SetLength(checked((long)libNewSize));
        }

        void Windows.Win32.System.Com.IStream.CopyTo(Windows.Win32.System.Com.IStream pstm, ulong cb, ulong* pcbRead, ulong* pcbWritten) => throw new NotImplementedException();

        void Windows.Win32.System.Com.IStream.Commit(STGC grfCommitFlags) => throw new NotImplementedException();

        void Windows.Win32.System.Com.IStream.Revert() => throw new NotImplementedException();

        void Windows.Win32.System.Com.IStream.LockRegion(ulong libOffset, ulong cb, LOCKTYPE dwLockType) => throw new NotImplementedException();

        void Windows.Win32.System.Com.IStream.UnlockRegion(ulong libOffset, ulong cb, uint dwLockType) => throw new NotImplementedException();

        void Windows.Win32.System.Com.IStream.Stat(STATSTG* pstatstg, STATFLAG grfStatFlag) => throw new NotImplementedException();

        void Windows.Win32.System.Com.IStream.Clone(out Windows.Win32.System.Com.IStream ppstm) => throw new NotImplementedException();
    }

    // The COM class information is looked up on the exact runtime type, so derived types need to be marked as well
    [GeneratedComClass]
    internal partial class StreamXamlInput
    {
    }

    [GeneratedComClass]
    internal partial class StreamXbfOutput
    {
    }
}